import { useTranslation } from '@fanfanlo';
import { Box, Button } from '@mui/material';
import type { IScript } from '../scripts/IScript';

// 日志前缀
const LOG_PREFIX = '[ScriptControlBar]';

interface ScriptControlBarProps {
  scriptData: IScript | null;
  onRun: () => void;
}

/**
 * 脚本控制按钮栏组件
 * 包含运行按钮等控制按钮
 */
export function ScriptControlBar({ scriptData, onRun }: ScriptControlBarProps) {
  console.log(`${LOG_PREFIX} 组件初始化, scriptData 是否存在: ${!!scriptData}`);

  const { t } = useTranslation('homepage/components/script-editor/content/v2/content');

  const handleRun = () => {
    console.log(`${LOG_PREFIX} 运行按钮被点击`);

    if (!scriptData) {
      console.log(`${LOG_PREFIX} scriptData 为空, 无法运行`);
      return;
    } else {
      console.log(`${LOG_PREFIX} scriptData 存在, 准备运行脚本`);
    }

    if (!scriptData.script || scriptData.script.trim() === '') {
      console.log(`${LOG_PREFIX} 脚本内容为空, 无法运行`);
      return;
    } else {
      console.log(`${LOG_PREFIX} 脚本内容长度: ${scriptData.script.length}`);
    }

    onRun();
    console.log(`${LOG_PREFIX} onRun 回调已执行`);
  };

  const isDisabled = !scriptData || !scriptData.script || scriptData.script.trim() === '';
  console.log(`${LOG_PREFIX} 运行按钮是否禁用: ${isDisabled}`);

  return (
    <Box>
      <Button variant="contained" onClick={handleRun} disabled={isDisabled} data-testid="ScriptControlBar__runButton__01JG2B0085">
        {t('ScriptControlBar.run')}
      </Button>
    </Box>
  );
}
